<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/espocrm/bootstrap.php';
use Espo\Core\{Application,AclManager,InjectableFactory};
use Espo\Core\ORM\EntityManager;
use Espo\Core\Tenant\{TenantContext,TenantContextStore};
use Espo\Core\Exceptions\{BadRequest,Forbidden,NotFound};
use Espo\Custom\Tools\MarketingEmail\PersonalizationHistoryService;
use Espo\Custom\Tools\LandingPage\{LandingPageService,LandingPageRenderer};

$checks=0;$assert=function(bool $ok,string $message)use(&$checks){$checks++;if(!$ok)throw new RuntimeException($message);};
$deny=function(callable $fn,string $message)use($assert){$denied=false;try{$fn();}catch(BadRequest|Forbidden|NotFound){$denied=true;}$assert($denied,$message);};
$app=new Application();$app->setupSystemUser();$c=$app->getContainer();$em=$c->getByClass(EntityManager::class);$factory=$c->getByClass(InjectableFactory::class);$contexts=$c->getByClass(TenantContextStore::class);$pdo=$em->getPDO();
$a=new TenantContext('30000000-0000-4000-8000-000000000001','isolation-alpha','history-test');$b=new TenantContext('30000000-0000-4000-8000-000000000002','isolation-beta','history-test');
$call=fn($fn)=>$contexts->runWith($a,$fn);$other=fn($fn)=>$contexts->runWith($b,$fn);$tx=$em->getTransactionManager();$tx->start();
try{
    $suffix=bin2hex(random_bytes(5));
    $make=fn($ctx,$type)=>$contexts->runWith($ctx,function()use($em,$type,$suffix,$ctx){$user=$em->createEntity('User',['userName'=>'history-'.$ctx->slug.'-'.$type.'-'.$suffix,'emailAddress'=>'history-'.$ctx->slug.'-'.$type.'-'.$suffix.'@example.test','type'=>$type,'isActive'=>true,'firstName'=>'History','lastName'=>$ctx->slug]);return $em->getEntityById('User',$user->getId());});
    $admin=$make($a,'admin');$staff=$make($a,'regular');$foreign=$make($b,'admin');
    $build=fn($user)=>$factory->createWith(PersonalizationHistoryService::class,['user'=>$user,'acl'=>$c->getByClass(AclManager::class)->createUserAcl($user)]);
    $service=$build($admin);$regular=$build($staff);$beta=$build($foreign);
    $contact=$call(fn()=>$em->createEntity('Contact',['firstName'=>'History','lastName'=>'Alpha '.$suffix]));$foreignContact=$other(fn()=>$em->createEntity('Contact',['firstName'=>'History','lastName'=>'Beta '.$suffix]));
    $metadata=['version'=>1,'matchMode'=>'all','conditions'=>[['field'=>'leadStatus','operator'=>'equals','value'=>'New','matched'=>true]],'branch'=>'matching','templateHash'=>str_repeat('a',64),'outputHash'=>str_repeat('b',64)];
    $insert=$pdo->prepare("INSERT INTO nexa_audit_event (id,tenant_id,service_id,actor_type,actor_user_id,action,subject_type,subject_id,correlation_id,source,metadata_json,occurred_at) VALUES (UUID(),?,?,'user',?,'personalization.evaluated','Contact',?,UUID(),'crm-record-hook',?,?)");
    $seed=function($ctx,$actor,$id,$meta,$date=null)use($insert){$insert->execute([$ctx->tenantId,$ctx->serviceId,$actor,$id,json_encode($meta),$date??gmdate('Y-m-d H:i:s').'.123456']);};
    for($i=0;$i<105;$i++)$seed($a,$admin->getId(),$contact->getId(),$metadata);
    $seed($b,$foreign->getId(),$foreignContact->getId(),$metadata);
    $count=(int)$pdo->query('SELECT COUNT(*) FROM nexa_audit_event')->fetchColumn();
    $input=['source'=>'email','search'=>$contact->getId()];
    $first=$call(fn()=>$service->history($input));$assert(count($first['list'])===100 && is_string($first['cursor']),'History must return bounded batches and a keyset cursor.');
    $next=$call(fn()=>$service->history($input+['cursor'=>$first['cursor']]));$assert(count($next['list'])===5 && $next['cursor']===null,'Keyset continuation must return the remainder without duplicates.');
    $assert(count(array_unique(array_column([...$first['list'],...$next['list']],'id')))===105,'Tied timestamps must not repeat or skip decisions.');
    $assert($first['list'][0]['outcome']==='Matching content' && $first['list'][0]['verification']==='Stored condition outcomes','Email history must reconstruct branch selection from stored truth values.');
    $assert($first['list'][0]['recordId']===$contact->getId(),'Native Contact identity should be linked only after permission checks.');
    $assert($first['policy']['editable']===false && $first['policy']['defaultWindowDays']===90,'Audit history must remain read-only; the default window is not a purge policy.');
    $assert((int)$pdo->query('SELECT COUNT(*) FROM nexa_audit_event')->fetchColumn()===$count,'Reading history must not mutate the shared ledger.');
    $deny(fn()=>$call(fn()=>$regular->history([])),'Regular users cannot access administrator decision history.');
    $deny(fn()=>$other(fn()=>$service->history([])),'A mismatched administrator cannot read another tenant context.');
    $deny(fn()=>$contexts->runWith(new TenantContext($a->tenantId,$a->slug,'history-test','','20000000-0000-4000-8000-000000000099'),fn()=>$service->history([])),'Administrator identity must match the service context.');
    $betaRows=$other(fn()=>$beta->history(['source'=>'email','search'=>$foreignContact->getId()]));$assert(count($betaRows['list'])===1,'Each tenant must read only its own native decisions.');
    $restricted=$metadata;$restricted['conditions'][0]['field']='tenantId';$restricted['conditions'][0]['value']='PRIVATE';$seed($a,$foreign->getId(),$contact->getId(),$restricted,gmdate('Y-m-d H:i:s',time()+1).'.123456');
    $redacted=$call(fn()=>$service->history($input))['list'][0];$assert($redacted['outcome']==='Evidence unavailable' && $redacted['details']===[],'Unavailable property evidence must be entirely redacted.');
    $assert($redacted['actor']==='Staff member' && !str_contains(json_encode($redacted),'PRIVATE'),'Foreign actor names and hidden comparison values must not leak.');
    $admin->set('isActive',false);$deny(fn()=>$call(fn()=>$service->history([])),'Inactive administrators cannot read history.');$admin->set('isActive',true);
    foreach([['source'=>'unknown'],['cursor'=>[]],['cursor'=>str_repeat('x',513)],['from'=>'2026-02-31'],['from'=>'2020-01-01','to'=>'2022-01-01'],['tenantId'=>$b->tenantId]] as $bad)$deny(fn()=>$call(fn()=>$service->history($bad)),'Malformed or identity-bearing filters must be rejected.');
    $recorder=$factory->createWith(\Espo\Custom\Tools\Customer\CustomerFoundationRecorder::class,['user'=>$admin]);
    $call(fn()=>$recorder->personalizationRecorded($contact->getId(),$metadata));
    $utc=$pdo->prepare("SELECT metadata_json,ABS(TIMESTAMPDIFF(SECOND,occurred_at,UTC_TIMESTAMP())) AS age_seconds FROM nexa_audit_event WHERE tenant_id=? AND service_id=? AND subject_id=? AND action='personalization.evaluated' AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json,'$.auditClock'))='UTC'");$utc->execute([$a->tenantId,$a->serviceId,$contact->getId()]);$clock=$utc->fetch(PDO::FETCH_ASSOC);
    $assert($clock && (int)$clock['age_seconds']<5,'New email decision evidence must use UTC independently of the database session timezone.');
    $customization=$factory->create(\Espo\Custom\Tools\Customization\CustomizationService::class);$fieldKey='history_'.$suffix;
    $field=$call(fn()=>$customization->saveDefinition('field',['entityType'=>'Contact','fieldKey'=>$fieldKey,'label'=>'History preference','dataType'=>'single_select','options'=>['Premium','Standard']]));
    $customContact=$call(fn()=>$em->createEntity('Contact',['firstName'=>'Property history','lastName'=>$suffix]));
    $customMetadata=$metadata;$customMetadata['conditions'][0]['field']='custom:'.$fieldKey;$customMetadata['conditions'][0]['value']='Premium';
    $call(fn()=>$recorder->personalizationRecorded($customContact->getId(),$customMetadata));
    $readable=$call(fn()=>$service->history(['search'=>$customContact->getId()]))['list'][0];$assert($readable['details'][0]['expected']==='Premium','Enabled tenant custom properties should have readable evidence.');
    $call(fn()=>$customization->archive('field',$field['id']));
    $hidden=$call(fn()=>$service->history(['search'=>$customContact->getId()]))['list'][0];$assert($hidden['details']===[] && !str_contains(json_encode($hidden),'Premium'),'Archiving a tenant property must redact retained comparison evidence immediately.');
    $malformed=$metadata;$malformed['conditions'][0]['field']=['leadStatus'];$call(fn()=>$recorder->personalizationRecorded($customContact->getId(),$malformed));
    $unavailable=$call(fn()=>$service->history(['search'=>$customContact->getId()]))['list'];$assert(count($unavailable)===2 && count(array_filter($unavailable,fn($row)=>$row['details']===[]))===2,'Malformed retained evidence must be unavailable rather than causing an internal error.');
    $invalidCursor=base64_encode(json_encode(['id'=>'11111111-1111-4111-8111-111111111111','at'=>'2026-99-99 99:99:99']));$deny(fn()=>$call(fn()=>$service->history(['cursor'=>$invalidCursor])),'Impossible cursor timestamps must fail before reaching SQL.');
    $landing=$factory->create(LandingPageService::class);$renderer=$factory->create(LandingPageRenderer::class);
    $page=$call(fn()=>$landing->save((object)['name'=>'History page','slug'=>'history-'.$suffix,'locale'=>'en','seoTitle'=>'History page','blocks'=>[(object)['id'=>'hero','type'=>'hero','heading'=>'Default heading','text'=>'Default body','personalization'=>(object)['field'=>'utm_source','value'=>'newsletter','heading'=>'Newsletter heading','text'=>'Newsletter body']]]]));
    $publication=$call(fn()=>$landing->publish($page['id']));preg_match('#/p/([a-f0-9]{48})/([^/]+)$#',$publication['url'],$url);
    $call(fn()=>$renderer->render($url[1],$url[2],['utm_source'=>'newsletter']));
    $history=$call(fn()=>$service->history(['source'=>'landing','search'=>$page['id']]));
    $assert(count($history['list'])===1 && $history['list'][0]['verification']==='Published version 1','Landing decisions must resolve the exact scoped immutable publication.');
    $assert($history['list'][0]['details'][0]['heading']==='Newsletter heading','Stored branch and publication must reconstruct the selected public heading.');
    $assert($history['list'][0]['actor']==='Anonymous visitor','Public decisions must not imply a trusted customer identity.');
    $assert($history['list'][0]['clock']==='UTC' && $first['list'][0]['clock']==='Legacy server time','New UTC evidence and unknown legacy clock bases must be labelled honestly.');
    $pdo->prepare("INSERT INTO nexa_audit_event (id,tenant_id,service_id,actor_type,action,subject_type,subject_id,correlation_id,source,metadata_json,occurred_at) SELECT UUID(),tenant_id,service_id,actor_type,action,subject_type,subject_id,UUID(),source,JSON_SET(metadata_json,'$.decisions[0].ruleHash','invalid'),UTC_TIMESTAMP(6)+INTERVAL 1 SECOND FROM nexa_audit_event WHERE tenant_id=? AND service_id=? AND subject_id=? AND action='personalization.rendered' LIMIT 1")->execute([$a->tenantId,$a->serviceId,$page['id']]);
    $broken=array_values(array_filter($call(fn()=>$service->history(['source'=>'landing','search'=>$page['id']]))['list'],fn($row)=>$row['outcome']==='Evidence unavailable'));$assert(count($broken)===1 && $broken[0]['details']===[],'Mismatched snapshot evidence must not be presented as verified.');
    echo "Personalization history checks passed: $checks (rollback-only).\n";
}catch(Throwable $error){fwrite(STDERR,get_class($error).': '.$error->getMessage()."\n".$error->getTraceAsString()."\n");throw $error;}finally{$tx->rollback();}
